use crate::{Error, Validator};
use std::future::Future;

/// Validation behavior implemented manually or generated by `#[derive(Validate)]`.
pub trait Validate: Sync {
    /// Validates this value with the provided validator configuration.
    fn validate(&self, validator: &Validator) -> impl Future<Output = Result<(), Error>> + Send;
}

#[doc(hidden)]
#[allow(missing_docs)]
pub trait Selective: Sync {
    #[doc(hidden)]
    fn __validate_with_context(
        &self,
        validator: &Validator,
        context: &crate::__private::Context<'_>,
    ) -> impl Future<Output = Result<(), Error>> + Send;
}
